import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

public class Solution {
  public static int[] fifoQueuePlacement(int queueCount, int sendMode, int[] groupOfMessage,
                                         int[] consumerOfQueue) {
    if (queueCount <= 0) throw new IllegalArgumentException("queue count must be positive");
    if (sendMode != 0 && sendMode != 1) throw new IllegalArgumentException("unknown send mode");
    if (consumerOfQueue == null || consumerOfQueue.length != queueCount) {
      throw new IllegalArgumentException("consumer array length mismatch");
    }
    if (groupOfMessage == null) throw new IllegalArgumentException("group array must not be null");
    for (int q = 0; q < queueCount; q++) {
      if (consumerOfQueue[q] < -1) throw new IllegalArgumentException("negative consumer index");
    }
    int m = groupOfMessage.length;
    int[] queueOf = new int[m];
    for (int i = 0; i < m; i++) {
      if (groupOfMessage[i] < 0) throw new IllegalArgumentException("negative group key");
      queueOf[i] = sendMode == 0 ? Math.floorMod(groupOfMessage[i], queueCount) : i % queueCount;
    }

    Map<Integer, Integer> seen = new HashMap<>();
    int[] consumerOf = new int[m];
    int[][] sortKey = new int[m][];
    int undeliverable = 0;
    for (int i = 0; i < m; i++) {
      int q = queueOf[i];
      int pos = seen.getOrDefault(q, 0);
      seen.put(q, pos + 1);
      consumerOf[i] = consumerOfQueue[q];
      sortKey[i] = consumerOf[i] < 0 ? null : new int[] {consumerOf[i], q, pos};
      if (consumerOf[i] < 0) undeliverable++;
    }
    List<Integer> observed = new ArrayList<>();
    for (int i = 0; i < m; i++) if (sortKey[i] != null) observed.add(i);
    observed.sort((a, b) -> {
      int[] ka = sortKey[a], kb = sortKey[b];
      for (int d = 0; d < 3; d++) if (ka[d] != kb[d]) return Integer.compare(ka[d], kb[d]);
      return Integer.compare(a, b);
    });

    Map<Integer, List<Integer>> byGroup = new TreeMap<>();
    for (int i = 0; i < m; i++) byGroup.computeIfAbsent(groupOfMessage[i], k -> new ArrayList<>()).add(i);
    Set<Integer> usedQueues = new HashSet<>();
    for (int q : queueOf) usedQueues.add(q);

    int spannedMax = 0, crossConsumer = 0, inversions = 0;
    for (Map.Entry<Integer, List<Integer>> e : byGroup.entrySet()) {
      Set<Integer> queues = new HashSet<>(), consumers = new HashSet<>();
      for (int i : e.getValue()) { queues.add(queueOf[i]); consumers.add(consumerOf[i]); }
      spannedMax = Math.max(spannedMax, queues.size());
      if (consumers.size() > 1) crossConsumer++;
      Set<Integer> members = new HashSet<>(e.getValue());
      List<Integer> seq = new ArrayList<>();
      for (int i : observed) if (members.contains(i)) seq.add(i);
      for (int a = 0; a < seq.size(); a++) {
        for (int b = a + 1; b < seq.size(); b++) if (seq.get(a) > seq.get(b)) inversions++;
      }
    }
    return new int[] {spannedMax, crossConsumer, inversions, undeliverable,
                      byGroup.size(), usedQueues.size()};
  }
}

