import java.util.HashSet;
import java.util.Set;

public class Solution {
  // "队列只是并行度，顺序由消费端排序兜住"版：发送一律轮询，并且宣称逆序对恒为 0。
  // 官方两条硬条件（同组同队列、单一生产者 + 串行发送）被当成实现细节忽略掉了。
  public static int[] fifoQueuePlacement(int queueCount, int sendMode, int[] groupOfMessage,
                                         int[] consumerOfQueue) {
    if (queueCount <= 0) throw new IllegalArgumentException("queue count must be positive");
    if (sendMode != 0 && sendMode != 1) throw new IllegalArgumentException("unknown send mode");
    if (consumerOfQueue == null || consumerOfQueue.length != queueCount) {
      throw new IllegalArgumentException("consumer array length mismatch");
    }
    if (groupOfMessage == null) throw new IllegalArgumentException("group array must not be null");
    int undeliverable = 0;
    Set<Integer> groups = new HashSet<>();
    Set<Integer> used = new HashSet<>();
    int m = groupOfMessage.length;
    for (int i = 0; i < m; i++) {
      if (groupOfMessage[i] < 0) throw new IllegalArgumentException("negative group key");
      int q = i % queueCount;
      used.add(q);
      if (consumerOfQueue[q] < 0) undeliverable++;
      groups.add(groupOfMessage[i]);
    }
    return new int[] {used.size(), 0, 0, undeliverable, groups.size(), used.size()};
  }
}
